import jdk.jfr.consumer.*;
import java.nio.file.*;
import java.time.*;
import java.io.*;
import java.util.*;

/** External measurement interpreter; no JVM attachment and no analyzer execution. */
public class LoopDemandQueryStageJfr {
    static class Window {
        final String name; final double begin,end; final Counts counts=new Counts();
        double pauseSeconds; long pauseEvents;
        Window(String n,double b,double e){name=n;begin=b;end=e;}
    }
    static class Trace {
        final List<String> frames; final String scope,site,observerComponent,fineDomain,fineStage;
        final ObservationPass observationPass;
        Set<String> unique;
        Trace(List<String> f,List<Integer> lines,boolean truncated,String s,String a){frames=f;scope=s;site=a;observerComponent=observerComponent(f); fineDomain=fineDomain(f); fineStage=fineStage(f,fineDomain);observationPass=observationPass(f,lines,truncated,observerComponent!=null);}
    }
    static final String RESTRICT_SCALAR="org.opentaint.dataflow.bidi.engine.LoopOutputRestriction.restrictScalar";
    static final int RAW_BASELINE_LINE=160,TRIAL_LINE=190;
    static class ObservationPass {
        final String category,reason;
        ObservationPass(String c,String r){category=c;reason=r;}
    }
    /** A complete stack without an observer is outside. Missing/truncated context is not guessed. */
    static ObservationPass observationPass(List<String> frames,List<Integer> lines,boolean truncated,boolean observer){
        if(frames.isEmpty())return new ObservationPass("unattributed","no_stack");
        if(truncated)return new ObservationPass("unattributed","truncated_stack");
        if(!observer)return new ObservationPass("outside_observer","complete_nonobserver_stack");
        int found=0,line=-1;
        for(int i=0;i<frames.size();i++)if(frames.get(i).equals(RESTRICT_SCALAR)){found++;line=lines.get(i);}
        if(found==0)return new ObservationPass("unattributed","missing_restrictScalar_frame");
        if(found!=1)return new ObservationPass("unattributed","ambiguous_restrictScalar_frames");
        if(line==RAW_BASELINE_LINE)return new ObservationPass("raw_baseline","source_line_160");
        if(line==TRIAL_LINE)return new ObservationPass("trial","source_line_190");
        return new ObservationPass("unattributed",line<=0?"unknown_source_line":"unrecognized_source_line_"+line);
    }
    static class Counts {
        long samples,allocationSamples,allocationBytes,gcEvents; double gcPauses;
        final Map<String,Long> scopes=new HashMap<>(),leaf=new HashMap<>(),inclusive=new HashMap<>();
        final Map<String,Long> allocationScopes=new HashMap<>(),allocationClasses=new HashMap<>(),allocationSites=new HashMap<>();
        final Map<String,Long> observerSamples=new HashMap<>(),observerAllocation=new HashMap<>();
        final Map<String,Long> observationPassSamples=new HashMap<>(),observationPassAllocation=new HashMap<>(),observerPassSamples=new HashMap<>(),observerPassAllocation=new HashMap<>();
        final Map<String,Long> observationPassFineSamples=new HashMap<>(),observationPassFineAllocation=new HashMap<>(),observationPassUnattributedSamples=new HashMap<>(),observationPassUnattributedAllocation=new HashMap<>();
        final Map<String,Long> fineSamples=new HashMap<>(),fineAllocation=new HashMap<>(),fineAllocationClasses=new HashMap<>(),fineLeaf=new HashMap<>(),fineSourceLines=new HashMap<>(),fineApplicationSamples=new HashMap<>();
        final Map<String,List<List<String>>> examples=new HashMap<>();
        void add(String kind,RecordedEvent event,Trace trace){
            if(kind.equals("jdk.GarbageCollection")){gcEvents++;gcPauses+=seconds(event.getDuration("sumOfPauses"));return;}
            if(kind.equals("jdk.ExecutionSample") && !trace.frames.isEmpty()){
                samples++; inc(fineSamples,trace.fineDomain+"/"+trace.fineStage,1);inc(fineLeaf,trace.fineDomain+"/"+trace.fineStage+"/"+trace.frames.get(0),1);
                addPass(trace,1,false);
                String direction=has(trace.frames,".LocalRelationApplication.applyRecordView")?"reverse":has(trace.frames,".LocalRelationApplication.applyRecord")?"direct":null; if(direction!=null)inc(fineApplicationSamples,trace.fineDomain+"/"+direction,1);
                for(RecordedFrame f:event.getStackTrace().getFrames()){RecordedMethod m=f.getMethod();String name=m.getType().getName()+"."+m.getName();if(name.contains(".BlockSummaryLinks.publish"))inc(fineSourceLines,name+":"+f.getLineNumber(),1);}
                inc(scopes,trace.scope,1);inc(leaf,trace.frames.get(0),1);if(trace.observerComponent!=null)inc(observerSamples,trace.observerComponent,1);
                if(trace.unique==null)trace.unique=new HashSet<>(trace.frames);
                for(String frame:trace.unique)inc(inclusive,frame,1);
                List<List<String>> xs=examples.computeIfAbsent(trace.scope,k->new ArrayList<>());
                if(xs.size()<5&&!xs.contains(trace.frames))xs.add(List.copyOf(trace.frames));
            }else if(kind.equals("jdk.ObjectAllocationSample")){
                long weight=event.getLong("weight");inc(fineAllocation,trace.fineDomain+"/"+trace.fineStage,weight);RecordedClass allocated=event.getClass("objectClass");inc(fineAllocationClasses,trace.fineDomain+"/"+trace.fineStage+"/"+(allocated==null?"?":className(allocated)),weight);allocationSamples++;allocationBytes+=weight;if(trace.observerComponent!=null)inc(observerAllocation,trace.observerComponent,weight);
                addPass(trace,weight,true);
                inc(allocationScopes,trace.scope,weight);inc(allocationSites,trace.site,weight);
                RecordedClass cls=event.getClass("objectClass");inc(allocationClasses,cls==null?"?":className(cls),weight);
            }
        }
        void addPass(Trace trace,long weight,boolean allocation){
            String pass=trace.observationPass.category;
            inc(allocation?observationPassAllocation:observationPassSamples,pass,weight);
            inc(allocation?observationPassFineAllocation:observationPassFineSamples,pass+"/"+trace.fineDomain+"/"+trace.fineStage,weight);
            if(trace.observerComponent!=null)inc(allocation?observerPassAllocation:observerPassSamples,pass,weight);
            if(pass.equals("unattributed"))inc(allocation?observationPassUnattributedAllocation:observationPassUnattributedSamples,trace.observationPass.reason,weight);
        }
        Map<String,Object> output(){
            Map<String,Object> o=new LinkedHashMap<>();o.put("samples",samples);o.put("scopes",scopes);o.put("leaf",leaf);o.put("inclusive",inclusive);
            o.put("allocation_samples",allocationSamples);o.put("allocation_bytes",allocationBytes);o.put("allocation_scopes",allocationScopes);
            o.put("allocation_classes",allocationClasses);o.put("allocation_sites",allocationSites);o.put("gc_events",gcEvents);o.put("gc_pause_seconds",gcPauses);o.put("observer_samples",observerSamples);o.put("observer_allocation",observerAllocation);o.put("examples",examples);o.put("fine_samples",fineSamples);o.put("fine_allocation",fineAllocation);o.put("fine_allocation_classes",fineAllocationClasses);o.put("fine_leaf",fineLeaf);o.put("fine_source_lines",fineSourceLines);o.put("fine_application_samples",fineApplicationSamples);
            o.put("observation_pass_samples",observationPassSamples);o.put("observation_pass_allocation",observationPassAllocation);o.put("observer_pass_samples",observerPassSamples);o.put("observer_pass_allocation",observerPassAllocation);o.put("observation_pass_fine_samples",observationPassFineSamples);o.put("observation_pass_fine_allocation",observationPassFineAllocation);o.put("observation_pass_unattributed_samples",observationPassUnattributedSamples);o.put("observation_pass_unattributed_allocation",observationPassUnattributedAllocation);return o;
        }
    }


    static boolean has(List<String> frames,String... anchors){for(String frame:frames)for(String anchor:anchors)if(frame.contains(anchor))return true;return false;}
    static boolean isC5(String frame){return has(List.of(frame),".PreparedOutputPrograms", ".DemandStore.intersect", ".DemandStore.prepareLocalDataPlan", ".DemandStore.offerDataPair", ".BlockBoundaryDemandView.intersect", ".DemandStore.acceptsTarget", ".BlockBoundaryDemandView.acceptsTarget", ".LoopQueryScratch.plan", ".EntryRestrictionTicket.", ".AcceptedEntryOutput.");}
    static String fineDomain(List<String> f){
        if(has(f,".LoopPipelineTrace"))return "diagnostic_trace";
        if(has(f,".LoopConsumerObservation", ".MethodBlockRuntime.observe"))return "loop_observer";
        if(has(f,".LoopRestrictionSession", ".LoopOutputRestriction"))return "loop_gate";
        if(has(f,".OwnedJoinedStaticWriterBinding.complete",".OwnedJoinedStaticWriterBinding$complete"))return "joined_static_binding";
        if(has(f,".BlockSummaryLinks.publish"))return "local_publication";
        if(has(f,".BlockSummaryLinks.deliver",".BlockSummaryLinks.drain"))return "local_delivery";
        if(has(f,".PreparedExitDirectory"))return "prepared_routes";
        if(has(f,".KilledStaticWriteStore.freeze",".JoinedStaticSource.freezeWrites"))return "static_prune";
        if(f.stream().anyMatch(LoopDemandQueryStageJfr::isC5))return "summary_C5";
        if(has(f,".SavedRecordSelection", ".SavedRecordSelectionKt", ".MethodBlockRuntime.replaySaved"))return "saved_replay";
        if(has(f,".PersistedSummaryReplayKt.replayPersistedSummaries"))return "persisted_replay";
        if(has(f,".SubscriptionManager.onDelivery", ".SubscriptionManager.onTargetDelivery", ".SubscriptionManager.notifyTargets", ".SubscriptionManager.notify"))return "real_call_delivery";
        if(has(f,".SubscriptionManager.subscribe", ".SubscriptionManager.replay", ".SubscriptionManager.joinRequests", ".SubscriptionManager.onRequests", ".CalleeSubscriptions."))return "real_call_subscription";
        if(has(f,".RunMethodCallServices."))return "real_call_input";
        return "other";
    }
    static String realCallStage(List<String> f,String domain){
        if(has(f,".ApOps.satisfying", ".SummaryKt.satisfyingPart", ".SubscriptionManagerKt.matches"))return "full_AP_match";
        if(has(f,".ApOps.applySummary", ".SummaryKt.applySummaryPart", ".ApOps.applyRecordLeaf", ".RecordKt.applyRecord"))return "native_summary_or_record_application";
        if(has(f,".RunMethodCallServices.cleanChain", ".RunMethodCallServices$cleanChain", ".ApOps.cleanSelectedFullMask", ".ApOps.clean"))return "call_cleanup_or_field_action";
        if(has(f,".LimitKt.limitFacts", ".FieldLimitCut.", ".ApOps.limit", ".FlowSummaryNormalizationKt."))return "field_cut_or_normalization";
        if(has(f,".PathTrie.add"))return "current_input_or_publication_posting_index";
        if(has(f,".PathTrie."))return "candidate_path_index";
        if(has(f,".PublicationIndex.candidateMembers", ".PublicationIndex.candidates", ".SummaryStorage.candidates", ".SummaryStorage.targetCandidates", ".SummaryStorage.staticCandidates", ".CalleeSubscriptions.candidates"))return "candidate_lookup_or_snapshot";
        if(has(f,".RecordStore.byEntry", ".RecordStore.byExit", ".PersistentRecordStore.", ".Record.forEachReversedAt", ".Record.reversedLeavesAt"))return "persisted_record_selection_or_positions";
        if(has(f,".AddedFactAccumulator.add", ".AddedFactAccumulator.snapshot", ".CalleeSubscriptions.admit", ".CalleeSubscriptions$Admission"))return "current_input_merge_or_admission";
        if(has(f,".PublicationIndex.addAll", ".PublicationIndex.addTargets", ".SummaryStorage.publish", ".RunSummaryStore.", ".GroupStore."))return "publication_storage_or_index";
        if(has(f,".SubscriptionManager.joinRequests", ".SubscriptionManager.onRequests", ".SummaryStorage.borrowMatchingRequests"))return "request_matching_or_dispatch";
        if(has(f,".RunMethodCallServices.applyParts", ".RunMethodCallServices$applyParts", ".RunMethodCallServices.summaryParts", ".RunMethodCallServices.applySummary", ".RunMethodCallServices.applyRecord", ".RunMethodCallServices.applyRecordView", ".RunMethodCallServices.ndMatch"))return "native_summary_parts_or_outputs";
        if(has(f,".RunMethodCallServices.applyTarget", ".RunMethodCallServices.emitTargetBinding"))return "native_target_match_or_output";
        if(has(f,".RunMethodCallServices.resumeCallees", ".RunMethodCallServices.flow"))return "call_result_resume_or_stage_walk";
        if(has(f,".RunMethodCallServices.applyStage"))return "call_stage_edges_or_actions";
        if(has(f,".RunMethodCallServices.enterCallees"))return "callee_entry_or_initial_admission";
        return domain+"_other";
    }
    static String c5Stage(List<String> f){
        int end=-1;for(int i=0;i<f.size();i++)if(isC5(f.get(i)))end=i;
        if(end>=0)f=f.subList(0,end+1); // Exclude outer apply/limit callbacks that enclose this whole query.
        if(has(f,".LimitKt.limitFacts",".FieldLimitCut.",".ApOps.limit"))return "C5_field_limit";
        if(has(f,".ReferenceKt.marksMeet",".ReferenceKt.markSub",".MarkTable.coversAtom"))return "C5_mark_match";
        if(has(f,".ReferenceKt.restrictConclusionOnly", ".AcceptedEntryOutput.select", ".DemandKt.restrictFacts", ".EntryRestrictionTicket.restrict"))return "C5_native_scalar_restrict";
        if(has(f,".DemandScalarStreamsKt.packProgramStreams", ".DemandKt.packRestrictedSelections", ".ProtectionOutputs."))return "C5_program_pack_and_protection";
        if(has(f,".PreparedOutputPrograms$Builder", ".EntryRestrictionTicket.prepare", ".LoopQueryScratch.plan"))return "C5_prepare_or_plan_lookup";
        if(has(f,".FrozenDemandTrie", ".PathTrie."))return "C5_output_path_index";
        if(has(f,".ExactDemandResults."))return "C5_result_union";
        if(has(f,".DemandScalarStreamsKt.forEachDemandScalar", ".DemandScalarStreamsKt$forEachDemandScalar"))return "C5_scalar_stream_enumeration";
        return "C5_program_selection_or_bookkeeping";
    }
    static String fineStage(List<String> f,String domain){
        if(domain.equals("loop_observer")){
            int end=-1;for(int i=0;i<f.size();i++)if(has(List.of(f.get(i)),".LoopConsumerObservation", ".MethodBlockRuntime.observe"))end=i;
            f=f.subList(0,end+1);
            if(f.stream().anyMatch(LoopDemandQueryStageJfr::isC5))return c5Stage(f);
            if(has(f,".DemandStore.initials", ".LoopQueryScratch.initials"))return "C2_initial_admission";
            if(has(f,".PreparedExitDirectory"))return "prepared_route_selection";
            if(has(f,".LoopObservedFacts.",".EnclosingResults."))return "observation_result_union";
            if(has(f,".LocalRelationApplication.applyRecordView", ".ApOps.applyRecordLeaf"))return "reverse_saved_AP_application";
            if(has(f,".LocalRelationApplication.applyRecord"))return "direct_saved_AP_application";
            if(has(f,".SavedRecordSelection", ".SavedRecordSelectionKt", ".PersistentRecordStore.", ".Record.forEachReversedAt", ".Record.reversedLeavesAt", ".MethodBlockRuntime.savedRows", ".MethodBlockRuntime$savedRows"))return "saved_record_selection_or_positions";
            if(has(f,".NormalTargetStore.",".NormalTargetView."))return "normal_target_lookup";
            if(has(f,".FlowSummaryNormalizationKt.",".MethodExitMetadataKt."))return "normalization_or_metadata";
            return "observer_other";
        }
        if(domain.equals("summary_C5"))return c5Stage(f);
        if(domain.equals("real_call_subscription")||domain.equals("real_call_delivery")||domain.equals("real_call_input")||domain.equals("persisted_replay"))return realCallStage(f,domain);
        if(domain.equals("loop_gate")){
            if(has(f,".FrozenDemandTrie", ".AnyDemandCursor"))return "certificate_demand_cursor_walk";
            if(has(f,".RestrictedInitialPolicy.emit"))return "certificate_native_C2_image";
            if(has(f,".LoopRestrictionSession"))return "certificate_control_or_membership";
            return "native_prefix_limit_or_search";
        }
        if(domain.equals("joined_static_binding")){
            if(has(f,".LimitKt.limitFacts",".FieldLimitCut.",".ApOps.limit"))return "field_limit";
            if(has(f,".ApOps.satisfying",".SummaryKt.satisfyingPart"))return "input_matching";
            if(has(f,".ApOps.applySummary",".SummaryKt.applySummaryPart"))return "native_summary_application";
            if(has(f,".StaticWriteKeyInterner.intern",".StaticWriteKeyInterner.row"))return "raw_key_intern_or_decode";
            if(has(f,".FrozenStaticCompletion$Builder.add",".PackedGuidanceCatalog",".StaticGuidanceKt.guidancePattern"))return "guidance_publication";
            if(has(f,".CalleeSubscriptions.visitJoinedCandidates",".JoinedCallerInputs.visit",".JoinedLocalInputs.visit"))return "standing_input_selection_or_scan";
            return "binding_other";
        }
        if(domain.equals("local_publication")){
            if(has(f,".ApOps.satisfying",".SummaryKt.satisfyingPart",".LocalRelationApplication.targetArmLayer"))return "standing_input_matching";
            if(has(f,".LocalInputDirectory.candidates"))return "standing_input_candidate_index";
            if(has(f,".PublicationIndex.addAll",".PublicationIndex.addTargets"))return "publication_index_admission";
            return "snapshot_or_delivery_enqueue";
        }
        if(domain.equals("prepared_routes"))return "oriented_live_destination_plan";
        if(domain.equals("saved_replay"))return "positional_saved_selection_or_replay";
        if(domain.equals("diagnostic_trace"))return has(f,".LoopPipelineTrace$Fields", ".LoopPipelineTrace$Recorder.record", ".LoopPipelineTrace.record")?"bounded_full_fact_serialization":"trace_flag_or_counter_check";
        return domain.equals("static_prune")?"freeze":domain.equals("local_delivery")?"apply_or_queue":"other";
    }
    static final String[][] COMPONENTS={
        {"C2_initial_admission",".DemandStore.initials",".LoopQueryScratch.initials"},
        {"C5_enclosing_restriction",".PreparedOutputPrograms", ".DemandStore.intersect",".DemandStore.prepareLocalDataPlan",".EntryRestrictionTicket.",".AcceptedEntryOutput.",".LoopQueryScratch.plan",".BlockBoundaryDemandView.intersect",".DemandStore.acceptsTarget",".BlockBoundaryDemandView.acceptsTarget"},
        {"prepared_route_selection",".PreparedExitDirectory"},
        {"normal_target_lookup",".NormalTargetStore.",".NormalTargetView."},
        {"saved_record_enumeration",".SavedRecordSelection", ".SavedRecordSelectionKt", ".PersistentRecordStore.",".MethodBlockRuntime.savedRows",".MethodBlockRuntime$savedRows",".Record.reversedLeavesAt",".Record.forEachReversedAt"},
        {"saved_record_application",".LocalRelationApplication.applyRecord",".LocalRelationApplication.applyRecordView",".LocalRelationApplication.applyMatched",".ApOps.applyRecordLeaf"},
        {"AP_normalization_or_exit_metadata",".FlowSummaryNormalizationKt.",".MethodExitMetadataKt.",".BlockRunState.adjustObservedMethodExit",".BlockRunState.adjustMethodExitMetadata"},
        {"observation_result_union",".LoopObservedFacts.",".EnclosingResults."}
    };
    static String observerComponent(List<String> frames){
        int end=-1;for(int i=0;i<frames.size();i++)if(frames.get(i).contains(".LoopConsumerObservation")||frames.get(i).contains(".MethodBlockRuntime.observe"))end=i;
        if(end<0)return null;
        for(int i=0;i<=end;i++)for(String[] component:COMPONENTS)for(int j=1;j<component.length;j++)if(frames.get(i).contains(component[j]))return component[0];
        return "observer_control_or_other";
    }
    static void control(String name,String domain,String stage,String component,String... frames){
        List<String> stack=Arrays.asList(frames);String gotDomain=fineDomain(stack),gotStage=fineStage(stack,gotDomain),gotComponent=observerComponent(stack);
        if(!domain.equals(gotDomain)||!stage.equals(gotStage)||!Objects.equals(component,gotComponent))throw new AssertionError(name+": "+gotDomain+"/"+gotStage+"/"+gotComponent);
    }
    static void passControl(String name,String category,String reason,boolean truncated,List<Integer> lines,String... frames){
        List<String> stack=Arrays.asList(frames);ObservationPass got=observationPass(stack,lines,truncated,observerComponent(stack)!=null);
        if(!category.equals(got.category)||!reason.equals(got.reason))throw new AssertionError(name+": "+got.category+"/"+got.reason);
    }
    static void selfTest(){
        String obs="x.LoopConsumerObservation.observe", prog="x.PreparedOutputPrograms.intersect";
        control("C5 trie","loop_observer","C5_output_path_index","C5_enclosing_restriction","x.FrozenDemandTrie.visitNativeOrder",prog,obs);
        control("C2 trie","loop_observer","C2_initial_admission","C2_initial_admission","x.FrozenDemandTrie.visitNativeOrder","x.DemandStore.initials",obs);
        control("scalar streams","loop_observer","C5_scalar_stream_enumeration","C5_enclosing_restriction","x.DemandScalarStreamsKt.forEachDemandScalar",prog,obs);
        control("whole program pack","loop_observer","C5_program_pack_and_protection","C5_enclosing_restriction","x.ProtectionOutputs.attach","x.DemandScalarStreamsKt.packProgramStreams",prog,obs);
        control("native select","loop_observer","C5_native_scalar_restrict","C5_enclosing_restriction","x.ReferenceKt.restrictConclusionOnly",prog,obs);
        control("prepare","loop_observer","C5_prepare_or_plan_lookup","C5_enclosing_restriction","x.PreparedOutputPrograms$Builder.offer","x.LoopQueryScratch.plan",obs);
        control("cursor","loop_gate","certificate_demand_cursor_walk",null,"x.FrozenDemandTrie$Cursor.follow","x.LoopRestrictionSession.certifiedFirstBudget");
        control("outer callback cut excluded","loop_observer","C5_output_path_index","C5_enclosing_restriction","x.FrozenDemandTrie.visitNativeOrder",prog,obs,"x.ApOps.limit");
        control("real inside C5 cut","loop_observer","C5_field_limit","C5_enclosing_restriction","x.ApOps.limit",prog,obs);
        control("prepared routes","prepared_routes","oriented_live_destination_plan",null,"x.PreparedExitDirectory.prepare","x.MethodBlockRuntime.onApplied");
        control("inverse candidate","local_publication","standing_input_candidate_index",null,"x.LocalInputDirectory.candidates","x.BlockSummaryLinks.publish");
        control("saved positions","saved_replay","positional_saved_selection_or_replay",null,"x.SavedRecordSelection.forEachReversedAt");
        control("reverse saved AP","loop_observer","reverse_saved_AP_application","saved_record_application","x.ApOps.applyRecordLeaf","x.SavedRecordSelection.forEachReversedAt",obs);
        control("trace overhead","diagnostic_trace","bounded_full_fact_serialization",null,"x.LoopPipelineTrace$Fields.finish");
        control("trace enabled check","diagnostic_trace","trace_flag_or_counter_check",null,"x.LoopPipelineTrace.enabled");
        control("trace recorder call","diagnostic_trace","bounded_full_fact_serialization",null,"x.LoopPipelineTrace$Recorder.record");
        control("unknown visible","other","other",null,"x.Unclassified.newMethod");
        control("real replay path index","real_call_subscription","candidate_path_index",null,"x.PathTrie.lookupPrefixes","x.PublicationIndex.candidates","x.SubscriptionManager.replay");
        control("real delivery candidate snapshot","real_call_delivery","candidate_lookup_or_snapshot",null,"x.CalleeSubscriptions.candidates","x.SubscriptionManager.onDelivery");
        control("real replay full match","real_call_subscription","full_AP_match",null,"x.ApOps.satisfying","x.SubscriptionManager.applyMatch","x.SubscriptionManager.replay");
        control("real delivery AP apply","real_call_delivery","native_summary_or_record_application",null,"x.ApOps.applySummary","x.RunMethodCallServices.applyParts","x.SubscriptionManager.onDelivery");
        control("real subscription admission","real_call_subscription","current_input_merge_or_admission",null,"x.AddedFactAccumulator.add","x.CalleeSubscriptions.admit","x.SubscriptionManager.subscribe");
        control("call cleaner","real_call_input","call_cleanup_or_field_action",null,"x.ApOps.clean","x.RunMethodCallServices.cleanChain","x.RunMethodCallServices.applyStage");
        control("call native output","real_call_input","native_summary_parts_or_outputs",null,"x.RunMethodCallServices.applyParts");
        control("call stage","real_call_input","call_stage_edges_or_actions",null,"x.RunMethodCallServices.applyStage");
        control("call target","real_call_input","native_target_match_or_output",null,"x.RunMethodCallServices.emitTargetBinding");
        control("persisted replay beats call wrapper","persisted_replay","full_AP_match",null,"x.ApOps.satisfying","x.PersistedSummaryReplayKt.replayPersistedSummaries","x.RunMethodCallServices.enterCallees");
        control("subscription broad unknown stage","real_call_subscription","real_call_subscription_other",null,"x.SubscriptionManager.replay");
        control("higher loop precedence","loop_observer","direct_saved_AP_application","saved_record_application","x.LocalRelationApplication.applyRecord",obs,"x.SubscriptionManager.replay");
        control("higher joined precedence","joined_static_binding","standing_input_selection_or_scan",null,"x.CalleeSubscriptions.visitJoinedCandidates","x.OwnedJoinedStaticWriterBinding.complete");
        passControl("raw baseline caller line","raw_baseline","source_line_160",false,List.of(1,160),obs,RESTRICT_SCALAR);
        passControl("trial caller line","trial","source_line_190",false,List.of(1,190),obs,RESTRICT_SCALAR);
        passControl("no caller frame","unattributed","missing_restrictScalar_frame",false,List.of(1),obs);
        passControl("unknown caller line","unattributed","unknown_source_line",false,List.of(1,-1),obs,RESTRICT_SCALAR);
        passControl("unexpected caller line","unattributed","unrecognized_source_line_180",false,List.of(1,180),obs,RESTRICT_SCALAR);
        passControl("truncated baseline","unattributed","truncated_stack",true,List.of(1,160),obs,RESTRICT_SCALAR);
        passControl("truncated no observer","unattributed","truncated_stack",true,List.of(1),"x.External.method");
        passControl("complete nonobserver","outside_observer","complete_nonobserver_stack",false,List.of(160),RESTRICT_SCALAR);
        passControl("no stack","unattributed","no_stack",false,List.of());
        passControl("ambiguous caller","unattributed","ambiguous_restrictScalar_frames",false,List.of(1,160,190),obs,RESTRICT_SCALAR,RESTRICT_SCALAR);
        Counts counts=new Counts();
        counts.addPass(new Trace(List.of(obs,RESTRICT_SCALAR),List.of(1,160),false,"test","test"),1,false);
