    v = {k: x for k, x in data.items() if k not in ['current', 'comparisons', 'changedIdentityEvidence']}
    v['current'] = data['current']  # Each current identity appears once.
    v['comparisons'] = {}
    for name, comparison in data['comparisons'].items():
        c = dict(comparison)
        c['baseline'] = {k: x for k, x in c['baseline'].items() if k != 'identities'}
        v['comparisons'][name] = c
    # Preserve every changed identity and its exact sink location, without repeated code flows.
    v['changedIdentityLocations'] = []
    for e in data.get('changedIdentityEvidence', []):
        def occurrence(item):
            return item.get('occurrence', item)
        v['changedIdentityLocations'].append({
            'identity': e['identity'],
            'current': [occurrence(i) for i in e.get('current', [])],
